CANALES_INICIALES = [
    ('Recomendación', 'Cliente recomendado por otro cliente'),
    ('Facebook', 'Redes sociales: Facebook'),
    ('TikTok', 'Redes sociales: TikTok'),
    ('WhatsApp', 'Contacto por WhatsApp'),
    ('Televisión', 'Publicidad en televisión'),
    ('Publicidad física', 'Volantes, afiches y publicidad en la calle'),
    ('Otro', 'Otro medio no listado'),
]

PERMISOS = {
    'view': 'Consultar canales de captación',
    'manage': 'Administrar canales de captación',
}

ROLES_AUTORIZADOS = ('gerente', 'jefe-comercial')


def sembrar_canales_y_permisos(apps, schema_editor):
    database = schema_editor.connection.alias
    CanalCaptacion = apps.get_model('core', 'CanalCaptacion')
    Permission = apps.get_model('core', 'Permission')
    Role = apps.get_model('core', 'Role')
    RolePermission = apps.get_model('core', 'RolePermission')

    if not CanalCaptacion.objects.using(database).exists():
        for nombre, descripcion in CANALES_INICIALES:
            CanalCaptacion.objects.using(database).create(
                nombre=nombre,
                nombre_normalizado=' '.join(nombre.split()).casefold(),
                descripcion=descripcion,
                activo=True,
            )

    permisos = {}
    for action, name in PERMISOS.items():
        permiso, _ = Permission.objects.using(database).get_or_create(
            module='captacion',
            action=action,
            defaults={'name': name},
        )
        permisos[action] = permiso

    for role_code in ROLES_AUTORIZADOS:
        role = Role.objects.using(database).filter(code=role_code).first()
        if role is None:
            continue
        for permiso in permisos.values():
            RolePermission.objects.using(database).get_or_create(
                role=role,
                permission=permiso,
            )


